def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "place_pregnancy_note_on_package": And([
            self.consent_to_deliver,
            Not(self.consent_to_disclose),
            self.private_request,
            self.helpful_intent
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
